-- 6. The Blackrock army around Dreadmaul Rock (Blackrock Invader 48432 and 48414, 680 or so): the targets of Assault on Dreadmaul Rock
--    (28320 Alliance, 28454 Horde: slay 200 Blackrock Invaders from the vehicle). TDB 8.3.7 has none of them while it has the
--    Necromancers, dragonspawn and ogres standing in the same place, so retail shows the army only to players on the quest.
--    Now: phase 319 in Burning Steppes, given while either quest is taken (not yet rewarded); phase 169 next to it so
--    every other spawn stays visible. Three stacked copies (under half a yard from another invader) removed.
DELETE FROM `creature` WHERE `guid` IN (313610,313734,313739) AND `id` IN (48414,48432);
DELETE FROM `creature_addon` WHERE `guid` IN (313610,313734,313739) AND `guid` NOT IN (SELECT `guid` FROM `creature`);
UPDATE `creature` SET `PhaseId`=319,`PhaseGroup`=0 WHERE `id` IN (48414,48432) AND `map`=0 AND `zoneId`=46;
DELETE FROM `phase_area` WHERE `AreaId`=46 AND `PhaseId` IN (169,319);
