(26,319,46,0,1,47,0,28454,10,0,0,0,0,'','Dreadmaul Rock army - Assault on Dreadmaul Rock (28454, Horde) taken or completed');

-- Summary: expect 0 Firegut Ogres, the army all in phase 319 (0 outside it), 2 phase rows, 2 conditions
SELECT (SELECT COUNT(*) FROM `creature` WHERE `id`=7033 AND `map`=0 AND `zoneId`=46) AS `firegut_ogres`,
       (SELECT COUNT(*) FROM `creature` WHERE `id` IN (48414,48432) AND `zoneId`=46 AND `PhaseId`=319) AS `army_phased`,
       (SELECT COUNT(*) FROM `creature` WHERE `id` IN (48414,48432) AND `zoneId`=46 AND `PhaseId`<>319) AS `army_unphased`,
       (SELECT COUNT(*) FROM `phase_area` WHERE `AreaId`=46) AS `phase_rows`,
       (SELECT COUNT(*) FROM `conditions` WHERE `SourceTypeOrReferenceId`=26 AND `SourceGroup`=319) AS `conditions`;
